// Tema 1 · Estatuto de Roma, parte 2 (arts. 53-102: págs. 84-100 del temario oficial / págs. 22-36 de tu PDF subrayado) · IA estilo examen (1-ia-1601…)
// + oficiales de tus marcas EX / EXAMEN 2020 (1-153…1-159) + citas literales para las oficiales de la academia.
// Uso: node prompts/herramientas/preguntas-t1-roma2.js [--json <salida.json>]
const AP = 'Estatuto de Roma de la Corte Penal Internacional';
const PREF = 'Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998';
const Q = [
// ── Art. 53 ──
{a: 'art. 53.1', r: 'Artículo 53. Inicio de una investigación', e: 'El fiscal, después de evaluar la información de que disponga, iniciará una investigación, a menos que determine que no existe fundamento razonable para proceder a ella. Al decidir si ha de iniciar una investigación, el fiscal tendrá en cuenta si (señale la INCORRECTA):',
 o: ['Existe una solicitud expresa del Consejo de Seguridad para iniciarla.', 'La información de que dispone constituye fundamento razonable para creer que se ha cometido o se está cometiendo un crimen de la competencia de la Corte.', 'La causa es o sería admisible de conformidad con el artículo 17.', 'Existen razones sustanciales para creer que, aun teniendo en cuenta la gravedad del crimen y los intereses de las víctimas, una investigación no redundaría en interés de la justicia.'],
 t: 'a) La información de que dispone constituye fundamento razonable para creer que se ha cometido o se está cometiendo un crimen de la competencia de la Corte. b) La causa es o sería admisible de conformidad con el artículo 17. c) Existen razones sustanciales para creer que, aun teniendo en cuenta la gravedad del crimen y los intereses de las víctimas, una investigación no redundaría en interés de la justicia', p: 'Son tres criterios; la solicitud del Consejo de Seguridad no es uno de ellos.'},
{a: 'art. 53.1', r: 'Artículo 53. Inicio de una investigación', e: 'El fiscal, si determinare que no hay fundamento razonable para proceder a la investigación y la determinación se basare únicamente en el apartado c) (que la investigación no redundaría en interés de la justicia), lo comunicará:',
 o: ['a la Sala de Cuestiones Preliminares.', 'al Consejo de Seguridad de las Naciones Unidas.', 'a la Presidencia de la Corte.', 'al Estado que haya remitido la situación.'],
 t: 'El fiscal, si determinare que no hay fundamento razonable para proceder a la investigación y la determinación se basare únicamente en el apartado c), lo comunicará a la Sala de Cuestiones Preliminares', p: 'La comunicación va a la Sala de Cuestiones Preliminares.'},
{a: 'art. 53.2', r: 'Artículo 53. Inicio de una investigación', e: 'Si, tras la investigación, el fiscal llega a la conclusión de que no hay fundamento suficiente para el enjuiciamiento, notificará su conclusión motivada a la Sala de Cuestiones Preliminares y:',
 o: ['al Estado que haya remitido el asunto o al Consejo de Seguridad si se trata de un caso previsto en el párrafo b) del artículo 13.', 'a la Asamblea de los Estados Partes y al Consejo de Seguridad de las Naciones Unidas.', 'al acusado y al Estado del que sea nacional.', 'a la Presidencia de la Corte y a las víctimas que hayan presentado observaciones.'],
 t: 'notificará su conclusión motivada a la Sala de Cuestiones Preliminares y al Estado que haya remitido el asunto de conformidad con el artículo 14 o al Consejo de Seguridad si se trata de un caso previsto en el párrafo b) del artículo 13', p: 'Además de a la Sala, al Estado remitente o al Consejo de Seguridad.'},
{a: 'art. 53.3', r: 'Artículo 53. Inicio de una investigación', e: 'La Sala de Cuestiones Preliminares podrá, de oficio, revisar una decisión del fiscal de no proceder a la investigación si dicha decisión se basare únicamente en el párrafo 1.c) o el párrafo 2.c). En ese caso, la decisión del fiscal:',
 o: ['únicamente surtirá efecto si es confirmada por la Sala de Cuestiones Preliminares.', 'surtirá efecto si no es revocada en el plazo de un mes por la Sala de Cuestiones Preliminares.', 'surtirá efecto desde su notificación, sin perjuicio de la revisión posterior.', 'únicamente surtirá efecto si es confirmada por la Presidencia de la Corte.'],
 t: 'la Sala de Cuestiones Preliminares podrá, de oficio, revisar una decisión del fiscal de no proceder a la investigación si dicha decisión se basare únicamente en el párrafo 1.c), o el párrafo 2.c). En ese caso, la decisión del fiscal únicamente surtirá efecto si es confirmada por la Sala de Cuestiones Preliminares', p: 'Sin confirmación de la Sala no surte efecto.'},
{a: 'art. 53.4', r: 'Artículo 53. Inicio de una investigación', e: 'El fiscal podrá reconsiderar en cualquier momento su decisión de iniciar una investigación o enjuiciamiento sobre la base de:',
 o: ['nuevos hechos o nuevas informaciones.', 'nuevos hechos o nuevas pruebas aportadas por los Estados.', 'nuevas informaciones recabadas por la Sala de Cuestiones Preliminares.', 'nuevos hechos, siempre con autorización de la Sala de Cuestiones Preliminares.'],
 t: 'El fiscal podrá reconsiderar en cualquier momento su decisión de iniciar una investigación o enjuiciamiento sobre la base de nuevos hechos o nuevas informaciones', p: 'Sobre la base de nuevos hechos o nuevas informaciones.'},
// ── Art. 54 ──
{a: 'art. 54.1', r: 'Artículo 54. Funciones y atribuciones del fiscal con respecto a las investigaciones', e: 'A fin de establecer la veracidad de los hechos, el fiscal ampliará la investigación a todos los hechos y las pruebas que sean pertinentes para determinar si hay responsabilidad penal de conformidad con el Estatuto y, a esos efectos, investigará:',
 o: ['tanto las circunstancias incriminantes como las eximentes.', 'únicamente las circunstancias incriminantes.', 'las circunstancias incriminantes, y las eximentes si lo solicita la defensa.', 'tanto las circunstancias agravantes como las atenuantes.'],
 t: 'A fin de establecer la veracidad de los hechos, ampliará la investigación a todos los hechos y las pruebas que sean pertinentes para determinar si hay responsabilidad penal de conformidad con el presente Estatuto y, a esos efectos, investigará tanto las circunstancias incriminantes como las eximentes', p: 'Investiga tanto las incriminantes como las eximentes.'},
{a: 'art. 54.1.b)', r: 'Artículo 54. Funciones y atribuciones del fiscal con respecto a las investigaciones', e: 'El fiscal adoptará medidas adecuadas para asegurar la eficacia de la investigación y el enjuiciamiento de los crímenes de la competencia de la Corte. A esos efectos, respetará los intereses y las circunstancias personales de víctimas y testigos, entre otros, la edad, el género y la salud, y tendrá en cuenta la naturaleza de los crímenes, en particular los de:',
 o: ['violencia sexual, violencia por razones de género y violencia contra los niños.', 'violencia sexual, violencia doméstica y violencia contra los niños.', 'violencia sexual, trata de personas y violencia contra los niños.', 'violencia por razones de género y violencia contra las personas mayores.'],
 t: 'tendrá en cuenta la naturaleza de los crímenes, en particular los de violencia sexual, violencia por razones de género y violencia contra los niños', p: 'Violencia sexual, por razones de género y contra los niños.'},
{a: 'art. 54.2', r: 'Artículo 54. Funciones y atribuciones del fiscal con respecto a las investigaciones', e: 'El fiscal podrá realizar investigaciones en el territorio de un Estado:',
 o: ['de conformidad con las disposiciones de la Parte IX, o según lo autoriza la Sala de Cuestiones Preliminares de conformidad con el párrafo 3.d) del artículo 57.', 'siempre que el Estado en cuyo territorio actúe lo autorice expresamente por escrito.', 'de conformidad con las disposiciones de la Parte IX, o según lo autorice el Consejo de Seguridad.', 'con autorización de la Presidencia de la Corte, sin necesidad de la cooperación del Estado.'],
 t: 'El fiscal podrá realizar investigaciones en el territorio de un Estado: a) De conformidad con las disposiciones de la Parte IX, o b) Según lo autoriza la Sala de Cuestiones Preliminares de conformidad con el párrafo 3.d) del artículo 57', p: 'Dos vías: Parte IX o autorización de la Sala de Cuestiones Preliminares.'},
{a: 'art. 54.3', r: 'Artículo 54. Funciones y atribuciones del fiscal con respecto a las investigaciones', e: 'El fiscal podrá (señale la INCORRECTA):',
 o: ['Decretar el arresto de las personas objeto de investigación.', 'Reunir y examinar pruebas.', 'Hacer comparecer e interrogar a las personas objeto de investigación, las víctimas y los testigos.', 'Solicitar la cooperación de un Estado u organización o acuerdo intergubernamental de conformidad con su respectiva competencia o mandato.'],
 t: 'a) Reunir y examinar pruebas; b) Hacer comparecer e interrogar a las personas objeto de investigación, las víctimas y los testigos; c) Solicitar la cooperación de un Estado u organización o acuerdo intergubernamental de conformidad con su respectiva competencia o mandato', p: 'La detención se decide por la Sala de Cuestiones Preliminares (art. 58).'},
{a: 'art. 54.3.d)', r: 'Artículo 54. Funciones y atribuciones del fiscal con respecto a las investigaciones', e: 'El fiscal podrá concertar las disposiciones o los acuerdos compatibles con el Estatuto que sean necesarios para facilitar la cooperación de:',
 o: ['un Estado, una organización intergubernamental o una persona.', 'un Estado o una organización intergubernamental, pero no una persona.', 'un Estado Parte o una organización regional.', 'un Estado, una organización no gubernamental o una persona.'],
 t: 'Concertar las disposiciones o los acuerdos compatibles con el presente Estatuto que sean necesarios para facilitar la cooperación de un Estado, una organización intergubernamental o una persona', p: 'La cooperación puede ser de un Estado, una organización intergubernamental o una persona.'},
{a: 'art. 54.3.e)', r: 'Artículo 54. Funciones y atribuciones del fiscal con respecto a las investigaciones', e: 'El fiscal podrá convenir en que no divulgará en ninguna etapa del procedimiento los documentos o la información que obtenga a condición de preservar su carácter confidencial y, únicamente, a los efectos de obtener nuevas pruebas, salvo:',
 o: ['con el acuerdo de quien haya facilitado la información.', 'con la autorización de la Sala de Cuestiones Preliminares.', 'cuando lo exija el interés de la justicia.', 'con el acuerdo de la defensa.'],
 t: 'Convenir en que no divulgará en ninguna etapa del procedimiento los documentos o la información que obtenga a condición de preservar su carácter confidencial y, únicamente, a los efectos de obtener nuevas pruebas, salvo con el acuerdo de quien haya facilitado la información', p: 'Solo con el acuerdo de quien facilitó la información.'},
// ── Art. 55 ──
{a: 'art. 55.1', r: 'Artículo 55. Derechos de las personas durante la investigación', e: 'En las investigaciones realizadas de conformidad con el Estatuto (señale la INCORRECTA):',
 o: ['Nadie será obligado a declarar contra sí mismo, salvo que exista una orden de la Sala de Cuestiones Preliminares.', 'Nadie será sometido a forma alguna de coacción, intimidación o amenaza, a torturas ni a otros tratos o castigos crueles, inhumanos o degradantes.', 'Quien haya de ser interrogado en un idioma que no sea el que comprende y habla perfectamente contará, sin cargo alguno, con los servicios de un intérprete competente.', 'Nadie será sometido a arresto o detención arbitrarios ni será privado de su libertad salvo por los motivos previstos en el Estatuto y de conformidad con los procedimientos establecidos en él.'],
 t: 'a) Nadie será obligado a declarar contra sí mismo ni a declararse culpable', p: 'El derecho a no declarar contra sí mismo ni declararse culpable no admite excepciones.'},
{a: 'art. 55.2', r: 'Artículo 55. Derechos de las personas durante la investigación', e: 'Cuando haya motivos para creer que una persona ha cometido un crimen de la competencia de la Corte y esa persona haya de ser interrogada por el fiscal o por las autoridades nacionales, tendrá además los derechos siguientes, de los que será informada antes del interrogatorio (señale la INCORRECTA):',
 o: ['A que el interrogatorio se grabe en vídeo en todo caso.', 'A ser informada de que existen motivos para creer que ha cometido un crimen de la competencia de la Corte.', 'A guardar silencio, sin que ello pueda tenerse en cuenta a los efectos de determinar su culpabilidad o inocencia.', 'A ser interrogada en presencia de su abogado, a menos que haya renunciado voluntariamente a su derecho a asistencia letrada.'],
 t: 'A ser informada de que existen motivos para creer que ha cometido un crimen de la competencia de la Corte; [...] A guardar silencio, sin que ello pueda tenerse en cuenta a los efectos de determinar su culpabilidad o inocencia; [...] A ser interrogada en presencia de su abogado, a menos que haya renunciado voluntariamente a su derecho a asistencia letrada', p: 'El Estatuto no prevé el derecho a la grabación en vídeo.'},
{a: 'art. 55.2.c)', r: 'Artículo 55. Derechos de las personas durante la investigación', e: 'La persona interrogada tiene derecho a ser asistida por un abogado defensor de su elección o, si no lo tuviere, a que se le asigne un defensor de oficio, siempre que fuere necesario en interés de la justicia, y, en cualquier caso:',
 o: ['sin cargo si careciere de medios suficientes.', 'con cargo a la Corte, aunque disponga de medios suficientes.', 'sin cargo, siempre que lo solicite al fiscal.', 'con cargo a la Corte si es condenada.'],
 t: 'A ser asistida por un abogado defensor de su elección o, si no lo tuviere, a que se le asigne un defensor de oficio, siempre que fuere necesario en interés de la justicia, y, en cualquier caso, sin cargo si careciere de medios suficientes', p: 'Sin cargo solo si carece de medios suficientes.'},
// ── Art. 56 ──
{a: 'art. 56.1', r: 'Artículo 56. Disposiciones que podrá adoptar la Sala de Cuestiones Preliminares cuando se presente una oportunidad única de proceder a una investigación', e: 'El fiscal, cuando considere que se presenta una oportunidad única de proceder a una investigación, que tal vez no se repita a los fines de un juicio, de recibir el testimonio o la declaración de un testigo o de examinar, reunir o verificar pruebas, lo comunicará:',
 o: ['a la Sala de Cuestiones Preliminares.', 'a la Sala de Primera Instancia.', 'a la Presidencia de la Corte.', 'al Secretario de la Corte.'],
 t: 'a) El fiscal, cuando considere que se presenta una oportunidad única de proceder a una investigación, que tal vez no se repita a los fines de un juicio, de recibir el testimonio o la declaración de un testigo o de examinar, reunir o verificar pruebas, lo comunicará a la Sala de Cuestiones Preliminares', p: 'Se comunica a la Sala de Cuestiones Preliminares.'},
{a: 'art. 56.2', r: 'Artículo 56. Disposiciones que podrá adoptar la Sala de Cuestiones Preliminares cuando se presente una oportunidad única de proceder a una investigación', e: 'Las medidas que podrá adoptar la Sala de Cuestiones Preliminares podrán consistir en (señale la INCORRECTA):',
 o: ['Dictar sentencia anticipada sobre los hechos investigados.', 'Formular recomendaciones o dictar ordenanzas respecto del procedimiento que habrá de seguirse.', 'Ordenar que quede constancia de las actuaciones.', 'Nombrar a un experto para que preste asistencia.'],
 t: 'a) Formular recomendaciones o dictar ordenanzas respecto del procedimiento que habrá de seguirse. b) Ordenar que quede constancia de las actuaciones. c) Nombrar a un experto para que preste asistencia', p: 'La Sala de Cuestiones Preliminares no dicta sentencias.'},
{a: 'art. 56.3', r: 'Artículo 56. Disposiciones que podrá adoptar la Sala de Cuestiones Preliminares cuando se presente una oportunidad única de proceder a una investigación', e: 'El fiscal podrá apelar de la decisión de la Sala de Cuestiones Preliminares de actuar de oficio con arreglo al presente párrafo. La apelación se sustanciará:',
 o: ['en un procedimiento sumario.', 'en un procedimiento ordinario.', 'ante la Sala de Primera Instancia.', 'con efecto suspensivo.'],
 t: 'El fiscal podrá apelar de la decisión de la Sala de Cuestiones Preliminares de actuar de oficio con arreglo al presente párrafo. La apelación se sustanciará en un procedimiento sumario', p: 'Procedimiento sumario.'},
// ── Art. 57 ──
{a: 'art. 57.2', r: 'Artículo 57. Funciones y atribuciones de la Sala de Cuestiones Preliminares', e: 'Las providencias u órdenes que la Sala de Cuestiones Preliminares dicte en virtud de los artículos 15, 18 o 19, el párrafo 2 del artículo 54, el párrafo 7 del artículo 61 o el artículo 72, deberán ser aprobadas por:',
 o: ['la mayoría de los magistrados que la componen.', 'unanimidad de los magistrados que la componen.', 'mayoría de dos tercios de los magistrados que la componen.', 'un solo magistrado de la Sala.'],
 t: 'deberán ser aprobadas por la mayoría de los magistrados que la componen', p: 'Mayoría de los magistrados de la Sala.'},
{a: 'art. 57.2.b)', r: 'Artículo 57. Funciones y atribuciones de la Sala de Cuestiones Preliminares', e: 'En todos los demás casos, un magistrado de la Sala de Cuestiones Preliminares podrá ejercer las funciones establecidas en el Estatuto, a menos que:',
 o: ['las Reglas de Procedimiento y Prueba dispongan otra cosa o así lo acuerde, por mayoría, la Sala de Cuestiones Preliminares.', 'las Reglas de Procedimiento y Prueba dispongan otra cosa o así lo acuerde, por unanimidad, la Sala.', 'lo solicite el fiscal o la defensa en el primer escrito.', 'lo decida la Presidencia de la Corte, a propuesta del fiscal.'],
 t: 'En todos los demás casos, un magistrado de la Sala de Cuestiones Preliminares podrá ejercer las funciones establecidas en el presente Estatuto, a menos que las Reglas de Procedimiento y Prueba dispongan otra cosa o así lo acuerde, por mayoría la Sala de Cuestiones Preliminares', p: 'Salvo que las Reglas lo dispongan o lo acuerde por mayoría la Sala.'},
{a: 'art. 57.3.d)', r: 'Artículo 57. Funciones y atribuciones de la Sala de Cuestiones Preliminares', e: 'La Sala de Cuestiones Preliminares podrá autorizar al fiscal a adoptar determinadas medidas de investigación en el territorio de un Estado Parte sin haber obtenido la cooperación de éste con arreglo a la Parte IX en el caso de que la Sala haya determinado que dicho Estado manifiestamente no está en condiciones de cumplir una solicitud de cooperación debido a que:',
 o: ['no existe autoridad u órgano alguno de su sistema judicial competente para cumplir una solicitud de cooperación.', 'se ha negado a cooperar en una solicitud anterior de la Corte.', 'no ha ratificado el Acuerdo sobre Privilegios e Inmunidades de la Corte.', 'su legislación interna prohíbe la ejecución de la medida solicitada.'],
 t: 'que dicho Estado manifiestamente no está en condiciones de cumplir una solicitud de cooperación debido a que no existe autoridad u órgano alguno de su sistema judicial competente para cumplir una solicitud de cooperación con arreglo a la Parte IX', p: 'El motivo es que no exista autoridad u órgano judicial competente para cumplir la solicitud.'},
{a: 'art. 57.3.e)', r: 'Artículo 57. Funciones y atribuciones de la Sala de Cuestiones Preliminares', e: 'Cuando se haya dictado una orden de detención o de comparecencia con arreglo al artículo 58, la Sala podrá recabar la cooperación de los Estados con arreglo al párrafo 1.k) del artículo 93 para adoptar medidas cautelares a los efectos de un decomiso que, en particular, beneficie en última instancia:',
 o: ['a las víctimas.', 'al Fondo Fiduciario de la Corte.', 'a los Estados Partes.', 'a la Corte Penal Internacional.'],
 t: 'recabar la cooperación de los Estados con arreglo al párrafo 1.k) del artículo 93 para adoptar medidas cautelares a los efectos de un decomiso que, en particular, beneficie en última instancia a las víctimas', p: 'El decomiso beneficia en última instancia a las víctimas.'},
// ── Art. 58 ──
{a: 'art. 58.1', r: 'Artículo 58. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares', e: 'En cualquier momento después de iniciada la investigación, la Sala de Cuestiones Preliminares dictará, a solicitud del fiscal, una orden de detención contra una persona si estuviere convencida de que hay motivo razonable para creer que ha cometido un crimen de la competencia de la Corte, y de que la detención parece necesaria para (señale la INCORRECTA):',
 o: ['Garantizar el pago de las costas del procedimiento.', 'Asegurar que la persona comparezca en juicio.', 'Asegurar que la persona no obstruya ni ponga en peligro la investigación ni las actuaciones de la Corte.', 'Impedir que la persona siga cometiendo ese crimen o un crimen conexo que sea de la competencia de la Corte y tenga su origen en las mismas circunstancias.'],
 t: 'Asegurar que la persona comparezca en juicio; [...] Asegurar que la persona no obstruya ni ponga en peligro la investigación ni las actuaciones de la Corte, o [...] impedir que la persona siga cometiendo ese crimen o un crimen conexo que sea de la competencia de la Corte y tenga su origen en las mismas circunstancias', p: 'Son tres finalidades; el pago de costas no es una de ellas.'},
{a: 'art. 58.2', r: 'Artículo 58. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares', e: 'La solicitud del fiscal de una orden de detención consignará (señale la INCORRECTA):',
 o: ['La identidad de los testigos de cargo que declararán en el juicio.', 'El nombre de la persona y cualquier otro dato que sirva para su identificación.', 'Una referencia expresa al crimen de la competencia de la Corte que presuntamente haya cometido.', 'La razón por la cual el fiscal crea necesaria la detención.'],
 t: 'a) El nombre de la persona y cualquier otro dato que sirva para su identificación; b) Una referencia expresa al crimen de la competencia de la Corte que presuntamente haya cometido; c) Una descripción concisa de los hechos que presuntamente constituyan esos crímenes; d) Un resumen de las pruebas y cualquier otra información que constituya motivo razonable para creer que la persona cometió esos crímenes, y e) La razón por la cual el fiscal crea necesaria la detención', p: 'La solicitud incluye un resumen de las pruebas, no la identidad de los testigos.'},
{a: 'art. 58.3', r: 'Artículo 58. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares', e: 'La orden de detención consignará:',
 o: ['el nombre de la persona y cualquier otro dato que sirva para su identificación, una referencia expresa al crimen de la competencia de la Corte por el que se pide su detención y una descripción concisa de los hechos.', 'el nombre de la persona, una referencia expresa al crimen y un resumen de las pruebas que constituyan motivo razonable.', 'el nombre de la persona, una referencia expresa al crimen y la razón por la cual se considera necesaria la detención.', 'el nombre de la persona y la fecha en que deberá ser puesta a disposición de la Corte.'],
 t: 'La orden de detención consignará: a) El nombre de la persona y cualquier otro dato que sirva para su identificación; b) Una referencia expresa al crimen de la competencia de la Corte por el que se pide su detención, y c) Una descripción concisa de los hechos que presuntamente constituyan esos crímenes', p: 'Resumen de pruebas y razón de la necesidad figuran en la solicitud del fiscal, no en la orden.'},
{a: 'art. 58.4 y 58.5', r: 'Artículo 58. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares', e: 'La orden de detención seguirá en vigor mientras la Corte no disponga lo contrario. La Corte, sobre la base de la orden de detención, podrá solicitar:',
 o: ['la detención provisional o la detención y entrega de la persona de conformidad con la Parte IX del Estatuto.', 'la detención provisional de la persona, pero no su entrega, de conformidad con la Parte IX.', 'la detención y entrega de la persona, con autorización del Consejo de Seguridad.', 'la detención provisional o la entrega de la persona de conformidad con la Parte V.'],
 t: 'La orden de detención seguirá en vigor mientras la Corte no disponga lo contrario. 5. La Corte, sobre la base de la orden de detención, podrá solicitar la detención provisional o la detención y entrega de la persona de conformidad con la Parte IX del presente Estatuto', p: 'Detención provisional o detención y entrega, conforme a la Parte IX.'},
{a: 'art. 58.6', r: 'Artículo 58. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares', e: 'El fiscal podrá pedir a la Sala de Cuestiones Preliminares que enmiende la orden de detención para modificar la referencia al crimen indicado en ésta o agregar otros. La Sala de Cuestiones Preliminares enmendará la orden si estuviere convencida de que:',
 o: ['hay motivo razonable para creer que la persona cometió los crímenes en la forma que se indica en esa modificación o adición.', 'existen pruebas suficientes de que la persona cometió los crímenes en la forma que se indica en esa modificación.', 'lo autoriza la Sala de Primera Instancia, previa audiencia del imputado.', 'hay fundamento suficiente para el enjuiciamiento por los nuevos crímenes.'],
 t: 'La Sala de Cuestiones Preliminares enmendará la orden si estuviere convencida de que hay motivo razonable para creer que la persona cometió los crímenes en la forma que se indica en esa modificación o adición', p: 'Basta «motivo razonable para creer».'},
{a: 'art. 58.7', r: 'Artículo 58. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares', e: 'El fiscal podrá pedir a la Sala de Cuestiones Preliminares que, en lugar de una orden de detención, dicte una orden de comparecencia. La Sala, de estar convencida de que hay motivo razonable para creer que la persona ha cometido el crimen que se le imputa y que bastará con una orden de comparecencia para asegurar que comparezca efectivamente, dictará una orden para que la persona comparezca, con o sin las condiciones limitativas de la libertad:',
 o: ['(distintas de la detención) que prevea el derecho interno.', '(incluida la detención domiciliaria) que prevea el derecho interno.', '(distintas de la detención) que prevea el Reglamento de la Corte.', '(incluidas las privativas de libertad) que prevea el derecho interno.'],
 t: 'dictará, con o sin las condiciones limitativas de la libertad (distintas de la detención), que prevea el derecho interno, una orden para que la persona comparezca', p: 'Las condiciones limitativas son distintas de la detención y las prevé el derecho interno.'},
{a: 'art. 58.7', r: 'Artículo 58. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares', e: 'La orden de comparecencia consignará el nombre de la persona y cualquier otro dato que sirva para su identificación, la fecha de la comparecencia, una referencia expresa al crimen y una descripción concisa de los hechos. La notificación de la orden será:',
 o: ['personal.', 'por edictos.', 'por conducto del Estado de la nacionalidad de la persona.', 'a través de su abogado defensor.'],
 t: 'La notificación de la orden será personal', p: 'La notificación de la orden de comparecencia es personal.'},
// ── Art. 59 ──
{a: 'art. 59.1', r: 'Artículo 59. Procedimiento de detención en el Estado de detención', e: 'El Estado Parte que haya recibido una solicitud de detención provisional o de detención y entrega tomará inmediatamente las medidas necesarias para la detención de conformidad con:',
 o: ['su derecho interno y con lo dispuesto en la Parte IX del Estatuto.', 'las Reglas de Procedimiento y Prueba de la Corte.', 'las instrucciones de la Sala de Cuestiones Preliminares.', 'lo dispuesto en la Parte V del Estatuto.'],
 t: 'El Estado Parte que haya recibido una solicitud de detención provisional o de detención y entrega tomará inmediatamente las medidas necesarias para la detención de conformidad con su derecho interno y con lo dispuesto en la Parte IX del presente Estatuto', p: 'Derecho interno y Parte IX.'},
{a: 'art. 59.2', r: 'Artículo 59. Procedimiento de detención en el Estado de detención', e: 'El detenido será llevado sin demora ante la autoridad judicial competente del Estado de detención, que determinará si, de conformidad con el derecho de ese Estado (señale la INCORRECTA):',
 o: ['Existen indicios suficientes de la comisión del crimen.', 'La orden le es aplicable.', 'La detención se llevó a cabo conforme a derecho.', 'Se han respetado los derechos del detenido.'],
 t: 'El detenido será llevado sin demora ante la autoridad judicial competente del Estado de detención, que determinará si, de conformidad con el derecho de ese Estado: [...] La orden le es aplicable; [...] La detención se llevó a cabo conforme a derecho, y [...] Se han respetado los derechos del detenido', p: 'La autoridad del Estado de detención no examina los indicios sobre el crimen.'},
{a: 'art. 59.4', r: 'Artículo 59. Procedimiento de detención en el Estado de detención', e: 'Al decidir la solicitud de libertad provisional, la autoridad competente del Estado de detención examinará si, dada la gravedad de los presuntos crímenes, hay circunstancias urgentes y excepcionales que justifiquen la libertad provisional y si existen las salvaguardias necesarias para que el Estado de detención pueda cumplir su obligación de entregar la persona a la Corte. Esa autoridad no podrá examinar:',
 o: ['si la orden de detención fue dictada conforme a derecho con arreglo a los apartados a) y b) del párrafo 1 del artículo 58.', 'si el detenido tiene arraigo en el territorio del Estado de detención.', 'si procede la libertad provisional, que corresponde exclusivamente a la Sala de Cuestiones Preliminares.', 'si existen las salvaguardias necesarias para la entrega a la Corte.'],
 t: 'Esa autoridad no podrá examinar si la orden de detención fue dictada conforme a derecho con arreglo a los apartados a) y b) del párrafo 1 del artículo 58', p: 'No puede revisar la legalidad de la orden de detención de la Corte.'},
{a: 'art. 59.5 y 59.6', r: 'Artículo 59. Procedimiento de detención en el Estado de detención', e: 'La solicitud de libertad provisional será notificada a la Sala de Cuestiones Preliminares, que hará recomendaciones a la autoridad competente del Estado de detención. Antes de adoptar su decisión, la autoridad competente del Estado de detención:',
 o: ['tendrá plenamente en cuenta esas recomendaciones, incluidas las relativas a medidas para impedir la evasión de la persona.', 'solicitará el consentimiento de la Sala de Cuestiones Preliminares.', 'quedará vinculada por esas recomendaciones, incluidas las relativas a medidas para impedir la evasión.', 'podrá prescindir de esas recomendaciones si lo exige su derecho interno.'],
 t: 'Antes de adoptar su decisión, la autoridad competente del Estado de detención tendrá plenamente en cuenta esas recomendaciones, incluidas las relativas a medidas para impedir la evasión de la persona', p: 'Las recomendaciones no vinculan, pero han de tenerse plenamente en cuenta.'},
{a: 'art. 59.7', r: 'Artículo 59. Procedimiento de detención en el Estado de detención', e: 'Una vez que el Estado de detención haya ordenado la entrega, el detenido será puesto a disposición de la Corte:',
 o: ['tan pronto como sea posible.', 'en el plazo máximo de setenta y dos horas.', 'en el plazo de diez días.', 'cuando lo acuerde el Consejo de Seguridad.'],
 t: 'Una vez que el Estado de detención haya ordenado la entrega, el detenido será puesto a disposición de la Corte tan pronto como sea posible', p: 'No hay plazo cifrado: tan pronto como sea posible.'},
// ── Art. 60 y 61 ──
{a: 'art. 60.2', r: 'Artículo 60. Primeras diligencias en la Corte', e: 'Quien sea objeto de una orden de detención podrá pedir la libertad provisional. Si la Sala de Cuestiones Preliminares está convencida de que se dan las condiciones enunciadas en el párrafo 1 del artículo 58, se mantendrá la detención. En caso contrario, la Sala:',
 o: ['pondrá en libertad al detenido, con o sin condiciones.', 'pondrá en libertad al detenido sin condiciones.', 'remitirá la decisión a la Sala de Primera Instancia.', 'pedirá informe al Estado de detención.'],
 t: 'En caso contrario, la Sala de Cuestiones Preliminares pondrá en libertad al detenido, con o sin condiciones', p: 'La libertad puede ser con o sin condiciones.'},
{a: 'art. 60.3', r: 'Artículo 60. Primeras diligencias en la Corte', e: 'La Sala de Cuestiones Preliminares revisará periódicamente su decisión en cuanto a la puesta en libertad o la detención, y podrá hacerlo en cualquier momento en que lo solicite:',
 o: ['el fiscal o el detenido.', 'el fiscal o el Estado de detención.', 'solo el detenido.', 'la Presidencia de la Corte.'],
 t: 'La Sala de Cuestiones Preliminares revisará periódicamente su decisión en cuanto a la puesta en libertad o la detención, y podrá hacerlo en cualquier momento en que lo solicite el fiscal o el detenido', p: 'A solicitud del fiscal o del detenido.'},
{a: 'art. 60.4', r: 'Artículo 60. Primeras diligencias en la Corte', e: 'La Sala de Cuestiones Preliminares se asegurará de que la detención en espera de juicio no se prolongue excesivamente a causa de una demora inexcusable del fiscal. Si se produjere dicha demora, la Corte:',
 o: ['considerará la posibilidad de poner en libertad al detenido, con o sin condiciones.', 'pondrá en libertad al detenido sin condiciones.', 'sustituirá al fiscal en el procedimiento.', 'archivará la causa contra el detenido.'],
 t: 'Si se produjere dicha demora, la Corte considerará la posibilidad de poner en libertad al detenido, con o sin condiciones', p: 'Solo «considerará la posibilidad» de la libertad.'},
{a: 'art. 60.5', r: 'Artículo 60. Primeras diligencias en la Corte', e: 'De ser necesario, la Sala de Cuestiones Preliminares podrá dictar una orden de detención para:',
 o: ['hacer comparecer a una persona que haya sido puesta en libertad.', 'impedir la evasión de una persona que haya sido condenada.', 'hacer comparecer a un testigo que se niegue a declarar.', 'ejecutar la sentencia dictada por la Sala de Primera Instancia.'],
 t: 'De ser necesario, la Sala de Cuestiones Preliminares podrá dictar una orden de detención para hacer comparecer a una persona que haya sido puesta en libertad', p: 'Sirve para hacer comparecer a quien fue puesto en libertad.'},
{a: 'art. 61.1', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'Dentro de un plazo razonable tras la entrega de la persona a la Corte o su comparecencia voluntaria ante ésta, la Sala de Cuestiones Preliminares celebrará una audiencia para confirmar los cargos sobre la base de los cuales el fiscal tiene la intención de pedir el procesamiento. La audiencia se celebrará en presencia:',
 o: ['del fiscal y del imputado, así como de su defensor.', 'del fiscal, del imputado y de las víctimas.', 'del fiscal y del defensor, aunque no del imputado.', 'del fiscal, del imputado y del Estado de detención.'],
 t: 'La audiencia se celebrará en presencia del fiscal y del imputado, así como de su defensor', p: 'Fiscal, imputado y defensor.'},
{a: 'art. 61.2', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'La Sala de Cuestiones Preliminares, a solicitud del fiscal o de oficio, podrá celebrar una audiencia en ausencia del acusado para confirmar los cargos cuando el imputado (señale la INCORRECTA):',
 o: ['Se encuentre detenido en un Estado que se niegue a entregarlo.', 'Haya renunciado a su derecho a estar presente.', 'Haya huido o no sea posible encontrarlo y se hayan tomado todas las medidas razonables para asegurar su comparecencia ante la Corte.', 'Haya huido o no sea posible encontrarlo y se le haya informado de los cargos y de que se celebrará una audiencia para confirmarlos.'],
 t: 'a) Haya renunciado a su derecho a estar presente, o b) Haya huido o no sea posible encontrarlo y se hayan tomado todas las medidas razonables para asegurar su comparecencia ante la Corte e informarle de los cargos y de que se celebrará una audiencia para confirmarlos', p: 'Solo son dos supuestos: renuncia y huida o imposibilidad de localizarlo.'},
{a: 'art. 61.3', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'Dentro de un plazo razonable antes de la audiencia, se proporcionará al imputado un ejemplar del documento en que se formulen los cargos por los cuales el fiscal se proponga enjuiciarlo, y:',
 o: ['se le informará de las pruebas que el fiscal se proponga presentar en la audiencia.', 'se le entregará copia de todas las pruebas que obren en poder del fiscal.', 'se le informará de la identidad de los testigos de cargo.', 'se le notificará el calendario del juicio oral.'],
 t: 'Dentro de un plazo razonable antes de la audiencia: a) Se proporcionará al imputado un ejemplar del documento en que se formulen los cargos por los cuales el fiscal se proponga enjuiciarlo, y b) Se le informará de las pruebas que el fiscal se proponga presentar en la audiencia', p: 'Se le informa de las pruebas que se presentarán en la audiencia.'},
{a: 'art. 61.4', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'Antes de la audiencia, el fiscal podrá proseguir la investigación y modificar o retirar los cargos. Se dará al imputado aviso con antelación razonable a la audiencia de cualquier modificación de los cargos o de su retiro. En caso de retirarse cargos, el fiscal comunicará las razones:',
 o: ['a la Sala de Cuestiones Preliminares.', 'al imputado y a su defensor.', 'a la Presidencia de la Corte.', 'a las víctimas.'],
 t: 'En caso de retirarse cargos, el fiscal comunicará las razones a la Sala de Cuestiones Preliminares', p: 'Las razones se comunican a la Sala de Cuestiones Preliminares.'},
{a: 'art. 61.5', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'En la audiencia, el fiscal presentará respecto de cada cargo pruebas suficientes de que hay motivos fundados para creer que el imputado cometió el crimen que se le imputa. El fiscal podrá presentar pruebas documentales o un resumen de las pruebas y:',
 o: ['no será necesario que llame a los testigos que han de declarar en el juicio.', 'deberá llamar a los testigos que han de declarar en el juicio.', 'deberá llamar a los testigos solo si lo solicita la defensa.', 'podrá llamar únicamente a los peritos.'],
 t: 'El fiscal podrá presentar pruebas documentales o un resumen de las pruebas y no será necesario que llame a los testigos que han de declarar en el juicio', p: 'No es necesario llamar a los testigos del juicio.'},
{a: 'art. 61.6', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'En la audiencia de confirmación de cargos, el imputado podrá (señale la INCORRECTA):',
 o: ['Retrasar el inicio del juicio.', 'Impugnar los cargos.', 'Impugnar las pruebas presentadas por el fiscal.', 'Presentar pruebas.'],
 t: 'En la audiencia, el imputado podrá: a) Impugnar los cargos; b) Impugnar las pruebas presentadas por el fiscal, y c) Presentar pruebas', p: 'Solo puede impugnar cargos y pruebas y presentar pruebas.'},
{a: 'art. 61.7', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'La Sala de Cuestiones Preliminares determinará, sobre la base de la audiencia, si existen pruebas suficientes de que hay motivos fundados para creer que el imputado cometió cada crimen que se le imputa. Según cual sea esa determinación, la Sala:',
 o: ['confirmará los cargos y asignará al acusado a una Sala de Primera Instancia, no confirmará los cargos con pruebas insuficientes o levantará la audiencia y pedirá al fiscal que considere nuevas pruebas o modificar un cargo.', 'confirmará los cargos y asignará al acusado a la Sala de Apelaciones, o no los confirmará y archivará la causa definitivamente.', 'confirmará los cargos, sin posibilidad de levantar la audiencia, o no los confirmará, con carácter definitivo.', 'confirmará los cargos y los remitirá a la Presidencia, que decidirá sobre su enjuiciamiento.'],
 t: 'Confirmará los cargos respecto de los cuales haya determinado que existen pruebas suficientes y asignará al acusado a una Sala de Primera Instancia para su enjuiciamiento por los cargos confirmados; [...] No confirmará los cargos respecto de los cuales haya determinado que las pruebas son insuficientes; [...] Levantará la audiencia y pedirá al fiscal que considere la posibilidad de', p: 'Tres posibilidades: confirmar y asignar a la Sala de Primera Instancia, no confirmar, o levantar la audiencia.'},
{a: 'art. 61.8', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'La no confirmación de un cargo por parte de la Sala de Cuestiones Preliminares no obstará para que el fiscal la pida nuevamente a condición de que:',
 o: ['presente pruebas adicionales.', 'presente nuevos testigos.', 'obtenga autorización de la Presidencia.', 'espere un plazo de seis meses.'],
 t: 'La no confirmación de un cargo por parte de la Sala de Cuestiones Preliminares no obstará para que el fiscal la pida nuevamente a condición de que presente pruebas adicionales', p: 'Debe presentar pruebas adicionales.'},
{a: 'art. 61.9', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'Una vez confirmados los cargos y antes de comenzar el juicio, el fiscal, con autorización de la Sala de Cuestiones Preliminares y previa notificación al acusado, podrá modificar los cargos. El fiscal, si se propusiera presentar nuevos cargos o sustituirlos por otros más graves, deberá pedir una audiencia de conformidad con el artículo 61 para confirmarlos. Una vez comenzado el juicio, el fiscal, con autorización de la Sala de Primera Instancia, podrá:',
 o: ['retirar los cargos.', 'modificar los cargos.', 'sustituir los cargos por otros más graves.', 'ampliar los cargos con nuevos hechos.'],
 t: 'Una vez comenzado el juicio, el fiscal, con autorización de la Sala de Primera Instancia, podrá retirar los cargos', p: 'Una vez comenzado el juicio solo puede retirar los cargos.'},
{a: 'art. 61.10 y 61.11', r: 'Artículo 61. Confirmación de los cargos antes del juicio', e: 'Una vez confirmados los cargos, la Presidencia constituirá una Sala de Primera Instancia. Además, toda orden ya dictada dejará de tener efecto con respecto a los cargos que:',
 o: ['no hayan sido confirmados por la Sala de Cuestiones Preliminares o hayan sido retirados por el fiscal.', 'no hayan sido apelados ante la Sala de Apelaciones en el plazo previsto.', 'hayan sido modificados por el fiscal tras la confirmación.', 'no hayan sido notificados personalmente al acusado.'],
 t: 'Toda orden ya dictada dejará de tener efecto con respecto a los cargos que no hayan sido confirmados por la Sala de Cuestiones Preliminares o hayan sido retirados por el fiscal', p: 'Pierde efecto respecto de cargos no confirmados o retirados.'},
// ── Parte IX: arts. 86 a 102 ──
{a: 'art. 86', r: 'Artículo 86. Obligación general de cooperar', e: 'Los Estados Partes, de conformidad con lo dispuesto en el Estatuto, __________ con la Corte en relación con la investigación y el enjuiciamiento de crímenes de su competencia.',
 o: ['cooperarán plenamente', 'colaborarán de buena fe', 'cooperarán en la medida de sus posibilidades', 'prestarán asistencia subsidiaria'],
 t: 'Los Estados Partes, de conformidad con lo dispuesto en el presente Estatuto, cooperarán plenamente con la Corte en relación con la investigación y el enjuiciamiento de crímenes de su competencia', p: 'La obligación es de cooperar plenamente.'},
{a: 'art. 87.1', r: 'Artículo 87. Solicitudes de cooperación: disposiciones generales', e: 'La Corte estará facultada para formular solicitudes de cooperación a los Estados Partes. Éstas se transmitirán por vía diplomática o por cualquier otro conducto adecuado que haya designado cada Estado Parte a la fecha de la ratificación, aceptación, aprobación o adhesión. Cuando proceda, y sin perjuicio de lo anterior, las solicitudes podrán transmitirse también por conducto de:',
 o: ['la Organización Internacional de Policía Criminal o de cualquier organización regional competente.', 'la Organización de las Naciones Unidas o de la Unión Europea.', 'la Organización Internacional de Policía Criminal o del Consejo de Seguridad.', 'cualquier organización internacional, con autorización del Estado requerido.'],
 t: 'Cuando proceda, y sin perjuicio de lo dispuesto en el apartado a), las solicitudes podrán transmitirse también por conducto de la Organización Internacional de Policía Criminal o de cualquier organización regional competente', p: 'La Organización Internacional de Policía Criminal (Interpol) o una organización regional competente.'},
{a: 'art. 87.2', r: 'Artículo 87. Solicitudes de cooperación: disposiciones generales', e: 'Las solicitudes de cooperación y los documentos que las justifiquen estarán redactados en un idioma oficial del Estado requerido, o acompañados de una traducción a ese idioma, o a uno de los idiomas de trabajo de la Corte, según:',
 o: ['la elección que haya hecho el Estado a la fecha de la ratificación, aceptación, aprobación o adhesión.', 'la elección que haga la Corte en cada solicitud.', 'lo que acuerden la Corte y el Estado requerido en cada caso.', 'la elección que haga el Estado en el momento de recibir la solicitud.'],
 t: 'o acompañados de una traducción a ese idioma, o a uno de los idiomas de trabajo de la Corte, según la elección que haya hecho el Estado a la fecha de la ratificación, aceptación, aprobación o adhesión', p: 'Según la elección que hizo el Estado al ratificar, aceptar, aprobar o adherirse.'},
{a: 'art. 87.3', r: 'Artículo 87. Solicitudes de cooperación: disposiciones generales', e: 'El Estado requerido preservará el carácter confidencial de toda solicitud de cooperación y de los documentos que las justifiquen:',
 o: ['salvo en la medida en que su divulgación sea necesaria para tramitarla.', 'salvo que la Corte autorice expresamente su divulgación.', 'en todo caso, sin excepción alguna.', 'salvo que el Estado requerido decida su publicación oficial.'],
 t: 'El Estado requerido preservará el carácter confidencial de toda solicitud de cooperación y de los documentos que las justifiquen, salvo en la medida en que su divulgación sea necesaria para tramitarla', p: 'La excepción es que la divulgación sea necesaria para tramitarla.'},
{a: 'art. 87.4', r: 'Artículo 87. Solicitudes de cooperación: disposiciones generales', e: 'Con respecto a las solicitudes de asistencia, la Corte podrá adoptar todas las medidas, incluidas las relativas a la protección de la información, que sean necesarias para proteger la seguridad y el bienestar físico o psicológico de:',
 o: ['las víctimas, los posibles testigos y sus familiares.', 'las víctimas y los testigos que declaren en el juicio.', 'los magistrados, el fiscal y sus familiares.', 'los testigos y los peritos que comparezcan ante la Corte.'],
 t: 'la Corte podrá adoptar todas las medidas, incluidas las relativas a la protección de la información, que sean necesarias para proteger la seguridad y el bienestar físico o psicológico de las víctimas, los posibles testigos y sus familiares', p: 'Las víctimas, los posibles testigos y sus familiares.'},
{a: 'art. 87.5 y 87.7', r: 'Artículo 87. Solicitudes de cooperación: disposiciones generales', e: 'Cuando un Estado no Parte que haya celebrado un arreglo especial o un acuerdo con la Corte se niegue a cooperar, o cuando un Estado Parte se niegue a dar curso a una solicitud de cooperación, impidiéndole ejercer sus funciones, la Corte podrá informar de ello o remitir la cuestión:',
 o: ['a la Asamblea de los Estados Partes o al Consejo de Seguridad, si éste le hubiese remitido el asunto.', 'a la Sala de Cuestiones Preliminares o a la Presidencia de la Corte.', 'al Secretario General de las Naciones Unidas o a la Asamblea General.', 'a la Asamblea de los Estados Partes y, en todo caso, al Consejo de Seguridad.'],
 t: 'la Corte podrá informar de ello a la Asamblea de los Estados Partes o al Consejo de Seguridad, si éste le hubiese remitido el asunto [...] ésta podrá hacer una constatación en ese sentido y remitir la cuestión a la Asamblea de los Estados Partes o al Consejo de Seguridad, si éste le hubiese remitido el asunto', p: 'A la Asamblea de los Estados Partes o, si remitió el asunto, al Consejo de Seguridad.'},
{a: 'art. 88', r: 'Artículo 88. Procedimientos aplicables en el derecho interno', e: 'Los Estados Partes se asegurarán de que en el derecho interno existan procedimientos aplicables a:',
 o: ['todas las formas de cooperación especificadas en la presente parte.', 'las solicitudes de detención y entrega de personas a la Corte.', 'las solicitudes de asistencia judicial formuladas por el fiscal.', 'las formas de cooperación que determine cada Estado Parte.'],
 t: 'Los Estados Partes se asegurarán de que en el derecho interno existan procedimientos aplicables a todas las formas de cooperación especificadas en la presente parte', p: 'Han de existir procedimientos para todas las formas de cooperación de la Parte IX.'},
{a: 'art. 89.2', r: 'Artículo 89. Entrega de personas a la Corte', e: 'Cuando la persona cuya entrega se pida la impugne ante un tribunal nacional oponiendo la excepción de cosa juzgada, el Estado requerido celebrará de inmediato consultas con la Corte para determinar si ha habido una decisión sobre la admisibilidad de la causa. Si la causa es admisible, el Estado requerido cumplirá la solicitud. Si está pendiente la decisión sobre la admisibilidad, el Estado requerido podrá:',
 o: ['aplazar la ejecución de la solicitud de entrega hasta que la Corte adopte esa decisión.', 'denegar la entrega hasta que la Corte adopte esa decisión.', 'ejecutar la entrega sin esperar la decisión de la Corte.', 'suspender la entrega durante un plazo máximo de seis meses.'],
 t: 'Si está pendiente la decisión sobre la admisibilidad, el Estado requerido podrá aplazar la ejecución de la solicitud de entrega hasta que la Corte adopte esa decisión', p: 'Puede aplazar la entrega hasta que la Corte decida.'},
{a: 'art. 89.3.d) y 89.3.e)', r: 'Artículo 89. Entrega de personas a la Corte', e: 'En caso de aterrizaje imprevisto en el territorio del Estado de tránsito, éste podrá pedir a la Corte que presente una solicitud de tránsito. El Estado de tránsito detendrá a la persona transportada mientras se recibe la solicitud de la Corte y se efectúa el tránsito; sin embargo, la detención no podrá prolongarse más de:',
 o: ['96 horas contadas desde el aterrizaje imprevisto si la solicitud no es recibida dentro de ese plazo.', '72 horas contadas desde el aterrizaje imprevisto si la solicitud no es recibida dentro de ese plazo.', '48 horas contadas desde el aterrizaje imprevisto si la solicitud no es recibida dentro de ese plazo.', '10 días contados desde el aterrizaje imprevisto si la solicitud no es recibida dentro de ese plazo.'],
 t: 'el Estado de tránsito detendrá a la persona transportada mientras se recibe la solicitud de la Corte y se efectúa el tránsito; sin embargo, la detención no podrá prolongarse más de 96 horas contadas desde el aterrizaje imprevisto si la solicitud no es recibida dentro de ese plazo', p: 'El plazo es de 96 horas.'},
{a: 'art. 89.3', r: 'Artículo 89. Entrega de personas a la Corte', e: 'Respecto del tránsito de una persona que otro Estado entregue a la Corte (señale la INCORRECTA):',
 o: ['Se requerirá siempre autorización del Estado de tránsito, incluso cuando la persona sea transportada por vía aérea y no se prevea aterrizar en su territorio.', 'El Estado Parte autorizará, de conformidad con su derecho procesal, el tránsito por su territorio, salvo cuando el tránsito obstaculice o demore la entrega.', 'La persona transportada permanecerá detenida durante el tránsito.', 'La solicitud de la Corte contendrá una descripción de la persona, una breve exposición de los hechos de la causa y su tipificación, y la orden de detención y entrega.'],
 t: 'd) No se requerirá autorización alguna cuando la persona sea transportada por vía aérea y no se prevea aterrizar en el territorio del Estado de tránsito', p: 'No se requiere autorización si el transporte es aéreo y no se prevé aterrizar.'},
{a: 'art. 89.4', r: 'Artículo 89. Entrega de personas a la Corte', e: 'Si la persona buscada está siendo enjuiciada o cumple condena en el Estado requerido por un crimen distinto de aquel por el cual se pide su entrega a la Corte, el Estado requerido, después de haber decidido conceder la entrega:',
 o: ['celebrará consultas con la Corte.', 'dará prioridad a la entrega a la Corte.', 'pospondrá la entrega hasta que concluya la condena.', 'solicitará autorización a la Sala de Cuestiones Preliminares.'],
 t: 'el Estado requerido, después de haber decidido conceder la entrega, celebrará consultas con la Corte', p: 'Tras decidir la entrega, celebra consultas con la Corte.'},
{a: 'art. 90.2', r: 'Artículo 90. Solicitudes concurrentes', e: 'Si el ESTADO REQUIRENTE ES UN ESTADO PARTE, el Estado requerido dará prioridad a la solicitud de la Corte cuando ésta haya determinado, de conformidad con los artículos 18 o 19, que la causa respecto de la cual se solicita la entrega es admisible y en su decisión haya tenido en cuenta:',
 o: ['la investigación o el enjuiciamiento que lleva a cabo el Estado requirente con respecto a la solicitud de extradición que éste ha presentado.', 'la nacionalidad de las víctimas y del presunto autor del crimen.', 'las fechas respectivas de las solicitudes de entrega y de extradición.', 'los intereses del Estado requirente y el lugar de comisión del crimen.'],
 t: 'Si el ESTADO REQUIRENTE ES UN ESTADO PARTE, el Estado requerido dará prioridad a la solicitud de la Corte cuando ésta: a) Haya determinado, de conformidad con lo dispuesto en los artículos 18 o 19, que la causa respecto de la cual se solicita la entrega es admisible y en su decisión haya tenido en cuenta la investigación o el enjuiciamiento que lleva a cabo el Estado requirente con respecto a la solicitud de extradición que éste ha presentado', p: 'La admisibilidad se decide teniendo en cuenta la investigación o el enjuiciamiento del Estado requirente.'},
{a: 'art. 90.4', r: 'Artículo 90. Solicitudes concurrentes', e: 'SI EL ESTADO REQUIRENTE NO ES PARTE EN EL ESTATUTO, el Estado requerido, en caso de que no esté obligado por alguna norma internacional a conceder la extradición al Estado requirente, dará prioridad a la solicitud de entrega que le haya hecho la Corte:',
 o: ['si ésta ha determinado que la causa era admisible.', 'en todo caso, aunque no haya determinado la admisibilidad de la causa.', 'si el Estado requirente lo consiente.', 'si lo autoriza el Consejo de Seguridad.'],
 t: 'SI EL ESTADO REQUIRENTE NO ES PARTE EN EL PRESENTE ESTATUTO, el Estado requerido, en caso de que no esté obligado por alguna norma internacional a conceder la extradición al Estado requirente, dará prioridad a la solicitud de entrega que le haya hecho la Corte si ésta ha determinado que la causa era admisible', p: 'La prioridad exige que la Corte haya determinado la admisibilidad.'},
{a: 'art. 90.6', r: 'Artículo 90. Solicitudes concurrentes', e: 'Para decidir si hace la entrega a la Corte o concede la extradición al Estado requirente que no sea parte en el Estatuto, el Estado requerido tendrá en cuenta todos los factores pertinentes, entre otros (señale la INCORRECTA):',
 o: ['La gravedad de la pena que se pueda imponer al acusado.', 'Las fechas respectivas de las solicitudes.', 'Los intereses del Estado requirente y, cuando proceda, si el crimen se cometió en su territorio y cuál es la nacionalidad de las víctimas y de la persona cuya entrega o extradición se ha solicitado.', 'La posibilidad de que la Corte y el Estado requirente lleguen posteriormente a un acuerdo respecto de la entrega.'],
 t: 'a) Las fechas respectivas de las solicitudes; b) Los intereses del Estado requirente y, cuando proceda, si el crimen se cometió en su territorio y cuál es la nacionalidad de las víctimas y de la persona cuya entrega o extradición se ha solicitado; y c) La posibilidad de que la Corte y el Estado requirente lleguen posteriormente a un acuerdo respecto de la entrega', p: 'La gravedad de la pena no es un factor del art. 90.6.'},
{a: 'art. 90.7', r: 'Artículo 90. Solicitudes concurrentes', e: 'Cuando el Estado Parte que reciba una solicitud de la Corte de entrega de una persona reciba también una solicitud de otro Estado relativa a la extradición de la misma persona por una conducta distinta de la que constituye el crimen, el Estado requerido, si no está obligado por ninguna norma internacional a conceder la extradición al Estado requirente:',
 o: ['dará preferencia a la solicitud de la Corte.', 'dará preferencia a la solicitud del Estado requirente.', 'decidirá libremente sin tener en cuenta la solicitud de la Corte.', 'consultará al Consejo de Seguridad.'],
 t: 'a) El Estado requerido, si no está obligado por ninguna norma internacional a conceder la extradición al Estado requirente, dará preferencia a la solicitud de la Corte', p: 'Si no está obligado a extraditar, prefiere la solicitud de la Corte.'},
{a: 'art. 91.1', r: 'Artículo 91. Contenido de la solicitud de detención y entrega', e: 'La solicitud de detención y entrega deberá formularse por escrito. En caso de urgencia, se podrá hacer por cualquier otro medio que permita dejar constancia escrita, a condición de que:',
 o: ['la solicitud sea confirmada en la forma indicada en el párrafo 1.a) del artículo 87.', 'la solicitud sea confirmada en el plazo de diez días.', 'la solicitud sea notificada a la Sala de Cuestiones Preliminares.', 'la solicitud sea autorizada por la Presidencia de la Corte.'],
 t: 'La solicitud de detención y entrega deberá formularse por escrito. En caso de urgencia, se podrá hacer por cualquier otro medio que permita dejar constancia escrita, a condición de que la solicitud sea confirmada en la forma indicada en el párrafo 1.a) del artículo 87', p: 'Debe confirmarse en la forma del art. 87.1.a).'},
{a: 'art. 91.2', r: 'Artículo 91. Contenido de la solicitud de detención y entrega', e: 'La solicitud de detención y entrega de una persona respecto de la cual la Sala de Cuestiones Preliminares haya dictado una orden de detención deberá contener los elementos siguientes o ir acompañada de:',
 o: ['información suficiente para la identificación de la persona buscada y datos sobre su probable paradero, y una copia de la orden de detención.', 'una copia de la orden de detención y de la sentencia condenatoria.', 'información para la identificación de la persona buscada y un resumen de las pruebas.', 'una copia de la orden de detención y la autorización de la Presidencia de la Corte.'],
 t: 'a) Información suficiente para la identificación de la persona buscada y datos sobre su probable paradero; b) Una copia de la orden de detención; y c) Los documentos, las declaraciones o la información que sean necesarios para cumplir los requisitos de procedimiento del Estado requerido relativos a la entrega', p: 'Identificación y paradero, copia de la orden y documentos necesarios.'},
{a: 'art. 91.2.c)', r: 'Artículo 91. Contenido de la solicitud de detención y entrega', e: 'Los requisitos de procedimiento del Estado requerido relativos a la entrega no podrán ser más onerosos que los aplicables a las solicitudes de extradición conforme a tratados o acuerdos celebrados por el Estado requerido y otros Estados y, de ser posible:',
 o: ['serán menos onerosos, habida cuenta del carácter específico de la Corte.', 'serán equivalentes, habida cuenta del carácter específico de la Corte.', 'serán idénticos a los de la extradición entre Estados.', 'serán más onerosos, cuando lo exija el derecho interno del Estado requerido.'],
 t: 'sin embargo, esos requisitos no podrán ser más onerosos que los aplicables a las solicitudes de extradición conforme a tratados o acuerdos celebrados por el Estado requerido y otros Estados y, de ser posible, serán menos onerosos, habida cuenta del carácter específico de la Corte', p: 'No más onerosos y, de ser posible, menos onerosos.'},
{a: 'art. 91.3', r: 'Artículo 91. Contenido de la solicitud de detención y entrega', e: 'La solicitud de detención y entrega del condenado deberá contener los siguientes elementos o ir acompañada de (señale la INCORRECTA):',
 o: ['Un informe del Estado en que cumplió condena anteriormente.', 'Copia de la orden de detención dictada en su contra.', 'Copia de la sentencia condenatoria.', 'Datos que demuestren que la persona buscada es aquella a la que se refiere la sentencia condenatoria.'],
 t: 'a) Copia de la orden de detención dictada en su contra; b) Copia de la sentencia condenatoria; c) Datos que demuestren que la persona buscada es aquella a la que se refiere la sentencia condenatoria, y d) Si la persona que se busca ha sido condenada a una pena, copia de la sentencia', p: 'No se exige informe de otro Estado sobre condenas anteriores.'},
{a: 'art. 92.2', r: 'Artículo 92. Detención provisional', e: 'La solicitud de detención provisional deberá hacerse por cualquier medio que permita dejar constancia escrita y contendrá (señale la INCORRECTA):',
 o: ['Una exposición completa de las pruebas que fundamenten la acusación.', 'Información suficiente para identificar a la persona buscada y datos sobre su probable paradero.', 'Una exposición concisa de los crímenes por los que se pida la detención y de los hechos que presuntamente serían constitutivos de esos crímenes.', 'Una declaración de que se presentará una solicitud de entrega de la persona buscada.'],
 t: 'a) Información suficiente para identificar a la persona buscada y datos sobre su probable paradero; b) Una exposición concisa de los crímenes por los que se pida la detención y de los hechos que presuntamente serían constitutivos de esos crímenes, inclusive, de ser posible, la indicación de la fecha y el lugar en que se cometieron; c) Una declaración de que existe una orden de detención o una decisión final condenatoria respecto de la persona buscada, y d) Una declaración de que se presentará una solicitud de entrega de la persona buscada', p: 'Basta una exposición concisa, sin pruebas completas.'},
{a: 'art. 92.3', r: 'Artículo 92. Detención provisional', e: 'La persona sometida a detención provisional podrá ser puesta en libertad si el Estado requerido no hubiere recibido la solicitud de entrega y los documentos que la justifiquen, de conformidad con el artículo 91, dentro del plazo fijado:',
 o: ['en las reglas de procedimiento y prueba.', 'en el Estatuto de Roma, que lo fija en sesenta días.', 'por la Sala de Cuestiones Preliminares en cada caso.', 'por el Estado requerido en su legislación.'],
 t: 'La persona sometida a detención provisional podrá ser puesta en libertad si el Estado requerido no hubiere recibido la solicitud de entrega y los documentos que la justifiquen, de conformidad con el artículo 91, dentro del plazo fijado en las reglas de procedimiento y prueba', p: 'El plazo lo fijan las reglas de procedimiento y prueba, no el Estatuto.'},
{a: 'art. 92.4', r: 'Artículo 92. Detención provisional', e: 'El hecho de que la persona buscada haya sido puesta en libertad de conformidad con el párrafo 3 no obstará para que sea:',
 o: ['nuevamente detenida y entregada una vez que el Estado requerido reciba la solicitud de entrega y los documentos que la justifiquen.', 'nuevamente detenida únicamente si la Sala de Cuestiones Preliminares lo autoriza.', 'entregada únicamente si presta su consentimiento a la entrega.', 'nuevamente detenida si comete un nuevo delito.'],
 t: 'El hecho de que la persona buscada haya sido puesta en libertad de conformidad con el párrafo 3 no obstará para que sea nuevamente detenida y entregada una vez que el Estado requerido reciba la solicitud de entrega y los documentos que la justifiquen', p: 'Puede volver a ser detenida y entregada al recibirse la solicitud.'},
{a: 'art. 93.1', r: 'Artículo 93. Otras formas de cooperación', e: 'Los Estados Partes deberán cumplir las solicitudes de asistencia formuladas por la Corte en relación con investigaciones o enjuiciamientos penales a fin de (señale la INCORRECTA):',
 o: ['Ejecutar las sentencias condenatorias dictadas por tribunales nacionales.', 'Identificar y buscar personas u objetos.', 'Practicar pruebas, incluidos los testimonios bajo juramento, y producir pruebas, incluidos los dictámenes e informes periciales que requiera la Corte.', 'Interrogar a una persona objeto de investigación o enjuiciamiento.'],
 t: 'a) Identificar y buscar personas u objetos; b) Practicar pruebas, incluidos los testimonios bajo juramento, y producir pruebas, incluidos los dictámenes e informes periciales que requiera la Corte; c) Interrogar a una persona objeto de investigación o enjuiciamiento', p: 'La ejecución de sentencias nacionales no es una forma de cooperación del art. 93.1.'},
{a: 'art. 93.2', r: 'Artículo 93. Otras formas de cooperación', e: 'La Corte podrá dar seguridades a los testigos o expertos que comparezcan ante ella de que no serán enjuiciados o detenidos ni se restringirá su libertad personal por:',
 o: ['un acto u omisión anterior a su salida del Estado requerido.', 'un acto u omisión posterior a su comparecencia ante la Corte.', 'un delito cometido en el territorio del Estado requerido.', 'un acto u omisión anterior a su comparecencia ante la Corte, incluso de otro Estado.'],
 t: 'La Corte podrá dar seguridades a los testigos o expertos que comparezcan ante ella de que no serán enjuiciados o detenidos ni se restringirá su libertad personal por un acto u omisión anterior a su salida del Estado requerido', p: 'Se refiere a actos anteriores a su salida del Estado requerido.'},
{a: 'art. 93.3', r: 'Artículo 93. Otras formas de cooperación', e: 'Cuando la ejecución de una determinada medida de asistencia estuviera prohibida en el Estado requerido por un principio fundamental de derecho ya existente y de aplicación general, el Estado requerido celebrará sin demora consultas con la Corte para tratar de resolver la cuestión. Si, después de celebrar consultas, no se pudiera resolver la cuestión:',
 o: ['la Corte modificará la solicitud según sea necesario.', 'el Estado requerido denegará definitivamente la solicitud.', 'la Corte remitirá la cuestión a la Asamblea de los Estados Partes.', 'el Estado requerido ejecutará la solicitud con carácter subsidiario.'],
 t: 'Si, después de celebrar consultas, no se pudiera resolver la cuestión, la Corte modificará la solicitud según sea necesario', p: 'Es la Corte la que modifica la solicitud.'},
{a: 'art. 93.4', r: 'Artículo 93. Otras formas de cooperación', e: 'El Estado Parte podrá no dar lugar a una solicitud de asistencia, en su totalidad o en parte, de conformidad con el artículo 72 y únicamente si la solicitud se refiere a:',
 o: ['la presentación de documentos o la divulgación de pruebas que afecten a su seguridad nacional.', 'la presentación de documentos que afecten a su orden público.', 'la divulgación de pruebas que afecten a sus relaciones diplomáticas.', 'la ejecución de medidas coercitivas que afecten a sus nacionales.'],
 t: 'El Estado Parte podrá no dar lugar a una solicitud de asistencia, en su totalidad o en parte, de conformidad con el artículo 72 y únicamente si la solicitud se refiere a la presentación de documentos o la divulgación de pruebas que afecten a su seguridad nacional', p: 'Solo por razones de seguridad nacional (art. 72).'},
{a: 'art. 93.6', r: 'Artículo 93. Otras formas de cooperación', e: 'Si no se da lugar a una solicitud de asistencia, el Estado Parte requerido deberá comunicar sin demora los motivos:',
 o: ['a la Corte o al fiscal.', 'a la Sala de Cuestiones Preliminares.', 'a la Asamblea de los Estados Partes.', 'a la Presidencia de la Corte.'],
 t: 'Si no se da lugar a una solicitud de asistencia, el Estado Parte requerido deberá comunicar sin demora los motivos a la Corte o al fiscal', p: 'Los motivos se comunican a la Corte o al fiscal.'},
{a: 'art. 93.7', r: 'Artículo 93. Otras formas de cooperación', e: 'La Corte podrá solicitar el traslado provisional de un detenido a los fines de su identificación o de que preste testimonio o asistencia de otra índole. El traslado podrá realizarse siempre que:',
 o: ['el detenido dé, libremente y con conocimiento de causa, su consentimiento, y el Estado requerido lo acepte, con sujeción a las condiciones que hubiere acordado con la Corte.', 'el detenido dé su consentimiento o lo autorice el Estado requerido.', 'el Estado requerido lo acepte, sin necesidad del consentimiento del detenido.', 'lo autorice la Sala de Cuestiones Preliminares, con el consentimiento del detenido.'],
 t: 'El traslado podrá realizarse siempre que: i) El detenido dé, libremente y con conocimiento de causa, su consentimiento, y ii) El Estado requerido lo acepte, con sujeción a las condiciones que hubiere acordado con la Corte', p: 'Se exigen ambos requisitos: consentimiento del detenido y aceptación del Estado.'},
{a: 'art. 93.8', r: 'Artículo 93. Otras formas de cooperación', e: 'El Estado requerido podrá, cuando sea necesario, transmitir al fiscal documentos o información con carácter confidencial. El fiscal únicamente podrá utilizarlos para:',
 o: ['reunir nuevas pruebas.', 'fundamentar la acusación.', 'presentarlos como prueba en el juicio.', 'su difusión a las partes en el proceso.'],
 t: 'El Estado requerido podrá, cuando sea necesario, transmitir al fiscal documentos o información con carácter confidencial. El fiscal únicamente podrá utilizarlos para reunir nuevas pruebas', p: 'Solo para reunir nuevas pruebas.'},
{a: 'art. 93.9', r: 'Artículo 93. Otras formas de cooperación', e: 'Cuando la solicitud de la Corte se refiera a información, bienes o personas que estén sometidos al control de un tercer Estado o de una organización internacional en virtud de un acuerdo internacional, el Estado requerido lo comunicará a la Corte y:',
 o: ['la Corte dirigirá su solicitud al tercer Estado o a la organización internacional.', 'el Estado requerido ejecutará la solicitud con autorización del tercer Estado.', 'la Corte remitirá la cuestión al Consejo de Seguridad.', 'el Estado requerido denegará la solicitud sin más trámite.'],
 t: 'cuando la solicitud de la Corte se refiera a información, bienes o personas que estén sometidos al control de un tercer Estado o de una organización internacional en virtud de un acuerdo internacional, el Estado requerido lo comunicará a la Corte y la Corte dirigirá su solicitud al tercer Estado o a la organización internacional', p: 'La Corte dirige su solicitud al tercer Estado o a la organización internacional.'},
{a: 'art. 94', r: 'Artículo 94. Aplazamiento de la ejecución de una solicitud de asistencia con respecto a una investigación o un enjuiciamiento en curso', e: 'Si la ejecución inmediata de una solicitud de asistencia interfiere una investigación o enjuiciamiento en curso de un asunto distinto de aquel al que se refiera la solicitud, el Estado requerido podrá aplazar la ejecución por el tiempo que acuerde con la Corte. No obstante, el aplazamiento:',
 o: ['no excederá de lo necesario para concluir la investigación o el enjuiciamiento de que se trate en el Estado requerido.', 'no excederá de seis meses, prorrogables por acuerdo con la Corte.', 'no excederá de un año, salvo autorización de la Sala de Cuestiones Preliminares.', 'no podrá ser superior al plazo de prescripción del delito investigado.'],
 t: 'el Estado requerido podrá aplazar la ejecución por el tiempo que acuerde con la Corte. No obstante, el aplazamiento no excederá de lo necesario para concluir la investigación o el enjuiciamiento de que se trate en el Estado requerido', p: 'No excederá de lo necesario para concluir la investigación o el enjuiciamiento en el Estado requerido.'},
{a: 'art. 95', r: 'Artículo 95. Aplazamiento de la ejecución de una solicitud por haberse impugnado la admisibilidad de la causa', e: 'Cuando la Corte proceda a examinar una impugnación de la admisibilidad de una causa de conformidad con los artículos 18 o 19, el Estado requerido podrá aplazar la ejecución de una solicitud hasta que la Corte se pronuncie sobre la impugnación, a menos que:',
 o: ['ésta haya resuelto expresamente que el fiscal podrá continuar recogiendo pruebas conforme a lo previsto en los artículos 18 o 19.', 'ésta haya resuelto expresamente que el fiscal podrá detener al acusado conforme a lo previsto en el artículo 58.', 'la Sala de Apelaciones haya ordenado la ejecución inmediata de la solicitud.', 'el Estado impugnante haya retirado su impugnación.'],
 t: 'el Estado requerido podrá aplazar la ejecución de una solicitud hecha de conformidad con esta Parte hasta que la Corte se pronuncie sobre la impugnación, a menos que ésta haya resuelto expresamente que el fiscal podrá continuar recogiendo pruebas conforme a lo previsto en los artículos 18 o 19', p: 'Salvo que la Corte haya resuelto expresamente que el fiscal continúe recogiendo pruebas.'},
{a: 'art. 96.1', r: 'Artículo 96. Contenido de la solicitud relativa a otras formas de asistencia de conformidad con el artículo 93', e: 'La solicitud relativa a otras formas de asistencia a que se hace referencia en el artículo 93 deberá hacerse por escrito. En caso de urgencia, se podrá hacer por cualquier otro medio que permita dejar constancia escrita, a condición de que:',
 o: ['la solicitud sea confirmada en la forma indicada en el párrafo 1.a) del artículo 87.', 'la solicitud sea confirmada en el plazo de setenta y dos horas.', 'la solicitud sea autorizada por la Sala de Cuestiones Preliminares.', 'la solicitud sea comunicada a la Asamblea de los Estados Partes.'],
 t: 'La solicitud relativa a otras formas de asistencia a que se hace referencia en el artículo 93 deberá hacerse por escrito. En caso de urgencia, se podrá hacer por cualquier otro medio que permita dejar constancia escrita, a condición de que la solicitud sea confirmada en la forma indicada en el párrafo 1.a) del artículo 87', p: 'Debe confirmarse en la forma del art. 87.1.a).'},
{a: 'art. 96.2', r: 'Artículo 96. Contenido de la solicitud relativa a otras formas de asistencia de conformidad con el artículo 93', e: 'La solicitud relativa a otras formas de asistencia deberá contener los siguientes elementos o estar acompañada de, según proceda (señale la INCORRECTA):',
 o: ['La identidad de los testigos que hayan de declarar en el juicio.', 'Una exposición concisa de su propósito y de la asistencia solicitada, incluidos los fundamentos jurídicos y los motivos de la solicitud.', 'La información más detallada posible acerca del paradero o la identificación de la persona o el lugar objeto de la búsqueda o la identificación.', 'Una exposición concisa de los hechos esenciales que fundamentan la solicitud.'],
 t: 'a) Una exposición concisa de su propósito y de la asistencia solicitada, incluidos los fundamentos jurídicos y los motivos de la solicitud; b) La información más detallada posible acerca del paradero o la identificación de la persona o el lugar objeto de la búsqueda o la identificación, de forma que se pueda prestar la asistencia solicitada; c) Una exposición concisa de los hechos esenciales que fundamentan la solicitud', p: 'No se exige identificar a los testigos del juicio.'},
{a: 'art. 97', r: 'Artículo 97. Consultas con la Corte', e: 'El Estado Parte que reciba una solicitud de conformidad con la Parte IX celebrará sin dilación consultas con la Corte si considera que la solicitud le plantea problemas que puedan obstaculizar o impedir su cumplimiento. Esos problemas podrían ser, entre otros (señale la INCORRECTA):',
 o: ['Que la persona buscada tenga la nacionalidad del Estado requerido.', 'Que la información fuese insuficiente para cumplir la solicitud.', 'Que, en el caso de una solicitud de entrega, la persona no pudiera ser localizada, pese a los intentos realizados, o que se hubiere determinado claramente que la persona en el Estado requerido no es la indicada en la solicitud.', 'Que el cumplimiento de la solicitud en su forma actual obligare al Estado requerido a no cumplir una obligación preexistente en virtud de un tratado con otro Estado.'],
 t: 'a) Que la información fuese insuficiente para cumplir la solicitud. b) Que, en el caso de una solicitud de entrega, la persona no pudiera ser localizada, pese a los intentos realizados, o que en la investigación realizada se hubiere determinado claramente que la persona en el Estado requerido no es la indicada en la solicitud, o c) Que el cumplimiento de la solicitud en su forma actual obligare al Estado requerido a no cumplir una obligación preexistente en virtud de un tratado con otro Estado', p: 'La nacionalidad de la persona buscada no figura entre los problemas del art. 97.'},
{a: 'art. 98.1', r: 'Artículo 98. Cooperación con respecto a la renuncia a la inmunidad y consentimiento a la entrega', e: 'La Corte no dará curso a una solicitud de entrega o de asistencia en virtud de la cual el Estado requerido deba actuar en forma incompatible con las obligaciones que le imponga el derecho internacional con respecto a la inmunidad de un Estado o la inmunidad diplomática de una persona o un bien de un tercer Estado, salvo que:',
 o: ['la Corte obtenga anteriormente la cooperación de ese tercer Estado para la renuncia a la inmunidad.', 'la Corte obtenga la autorización del Consejo de Seguridad.', 'el Estado requerido renuncie a la inmunidad en nombre del tercer Estado.', 'la Sala de Cuestiones Preliminares así lo decida expresamente.'],
 t: 'La Corte no dará curso a una solicitud de entrega o de asistencia en virtud de la cual el Estado requerido deba actuar en forma incompatible con las obligaciones que le imponga el derecho internacional con respecto a la inmunidad de un Estado o la inmunidad diplomática de una persona o un bien de un tercer Estado, salvo que la Corte obtenga anteriormente la cooperación de ese tercer Estado para la renuncia a la inmunidad', p: 'Salvo que la Corte obtenga antes la cooperación del tercer Estado para la renuncia a la inmunidad.'},
{a: 'art. 99.1 y 99.3', r: 'Artículo 99. Cumplimiento de las solicitudes a que se hace referencia en los artículos 93 y 96', e: 'Las solicitudes de asistencia se cumplirán de conformidad con el procedimiento aplicable en el derecho interno del Estado requerido y, salvo si ese derecho lo prohíbe, en la forma especificada en la solicitud. Las respuestas del Estado requerido serán transmitidas:',
 o: ['en su idioma y forma original.', 'en uno de los idiomas oficiales de la Corte.', 'en uno de los idiomas de trabajo de la Corte.', 'traducidas al idioma elegido por la Corte.'],
 t: 'Las respuestas del Estado requerido serán transmitidas en su idioma y forma original', p: 'En su idioma y forma original.'},
{a: 'art. 99.4', r: 'Artículo 99. Cumplimiento de las solicitudes a que se hace referencia en los artículos 93 y 96', e: 'Cuando resulte necesario en el caso de una solicitud que pueda ejecutarse sin necesidad de medidas coercitivas, el fiscal podrá ejecutar directamente la solicitud en el territorio de un Estado. Cuando el Estado Parte requerido fuere un Estado en cuyo territorio se hubiera cometido presuntamente el crimen, y hubiere habido una decisión de admisibilidad de conformidad con los artículos 18 o 19, el fiscal podrá ejecutar directamente la solicitud:',
 o: ['tras celebrar todas las consultas posibles con el Estado Parte requerido.', 'previa autorización de la Sala de Cuestiones Preliminares.', 'sin necesidad de consultar con el Estado Parte requerido.', 'previa autorización de la Presidencia de la Corte.'],
 t: 'a) Cuando el Estado Parte requerido fuere un Estado en cuyo territorio se hubiera cometido presuntamente el crimen, y hubiere habido una decisión de admisibilidad de conformidad con los artículos 18 ó 19, el fiscal podrá ejecutar directamente la solicitud tras celebrar todas las consultas posibles con el Estado Parte requerido', p: 'Tras celebrar todas las consultas posibles con el Estado Parte.'},
{a: 'art. 100.1', r: 'Artículo 100. Gastos', e: 'Los gastos ordinarios que se deriven del cumplimiento de las solicitudes en el territorio del Estado requerido correrán a cargo de éste, con excepción de los siguientes, que correrán a cargo de la Corte (señale la INCORRECTA):',
 o: ['Los gastos de las medidas coercitivas adoptadas por el Estado requerido.', 'Los gastos relacionados con el viaje y la seguridad de los testigos y peritos, o el traslado de personas detenidas.', 'Los gastos de traducción, interpretación y transcripción.', 'El costo de los informes o dictámenes periciales solicitados por la Corte.'],
 t: 'Los gastos ordinarios que se deriven del cumplimiento de las solicitudes en el territorio del Estado requerido correrán a cargo de éste, con excepción de los siguientes, que correrán a cargo de la Corte: a) Gastos relacionados con el viaje y la seguridad de los testigos y peritos, o el traslado, con arreglo al artículo 93, de personas detenidas; b) Gastos de traducción, interpretación y transcripción', p: 'Las medidas coercitivas son gasto ordinario del Estado requerido.'},
{a: 'art. 100.1', r: 'Artículo 100. Gastos', e: 'Correrán a cargo de la Corte los gastos de viaje y dietas de los magistrados, el fiscal, los fiscales adjuntos, el secretario, el secretario adjunto y los funcionarios de cualquier órgano de la Corte, así como los gastos relacionados con:',
 o: ['el transporte de la persona que entregue a la Corte un Estado de detención.', 'la custodia de la persona detenida en el Estado requerido.', 'la ejecución de las órdenes de la Corte por las autoridades nacionales.', 'la protección de las víctimas en el Estado requerido.'],
 t: 'e) Gastos relacionados con el transporte de la persona que entregue a la Corte un Estado de detención', p: 'El transporte de la persona entregada corre a cargo de la Corte.'},
{a: 'art. 100.2', r: 'Artículo 100. Gastos', e: 'Las disposiciones del párrafo 1 serán aplicables, según proceda, a las solicitudes hechas por los Estados Partes a la Corte. En ese caso, los gastos ordinarios que se deriven de su cumplimiento correrán a cargo:',
 o: ['de la Corte.', 'del Estado solicitante.', 'de la Asamblea de los Estados Partes.', 'de ambos por mitades.'],
 t: 'Las disposiciones del párrafo 1 serán aplicables, según proceda, a las solicitudes hechas por los Estados Partes a la Corte. En ese caso, los gastos ordinarios que se deriven de su cumplimiento correrán a cargo de la Corte', p: 'Aquí la Corte es la «requerida» y asume los gastos ordinarios.'},
{a: 'art. 101.1', r: 'Artículo 101. Principio de la especialidad', e: 'Quien haya sido entregado a la Corte en virtud del Estatuto no será procesado, castigado o detenido por una conducta anterior a su entrega, a menos que:',
 o: ['ésta constituya la base del delito por el cual haya sido entregado.', 'lo autorice la Sala de Cuestiones Preliminares.', 'lo consienta el Estado que hizo la entrega.', 'se trate de un crimen de lesa humanidad.'],
 t: 'Quien haya sido entregado a la Corte en virtud del presente Estatuto no será procesado, castigado o detenido por una conducta anterior a su entrega, a menos que ésta constituya la base del delito por el cual haya sido entregado', p: 'Salvo que la conducta sea la base del delito por el que fue entregado.'},
{a: 'art. 101.2', r: 'Artículo 101. Principio de la especialidad', e: 'La Corte podrá pedir al Estado que hizo la entrega que la dispense del cumplimiento de los requisitos del principio de la especialidad y, si fuere necesario, proporcionará información adicional de conformidad con el artículo 91. Los Estados Partes:',
 o: ['estarán facultados para dar esa dispensa a la Corte y procurarán hacerlo.', 'estarán obligados a dar esa dispensa a la Corte.', 'no podrán dar esa dispensa sin autorización de la Sala de Cuestiones Preliminares.', 'podrán dar esa dispensa únicamente en los crímenes de agresión.'],
 t: 'La Corte podrá pedir al Estado que hizo la entrega que la dispense del cumplimiento de los requisitos establecidos en el párrafo 1 y, si fuere necesario, proporcionará información adicional de conformidad con el artículo 91. Los Estados Partes estarán facultados para dar esa dispensa a la Corte y procurarán hacerlo', p: 'Están facultados para dispensarla y procurarán hacerlo.'},
{a: 'art. 102', r: 'Artículo 102. Términos empleados', e: 'A los efectos del Estatuto, por «extradición» se entenderá la entrega de una persona por un Estado a otro Estado de conformidad con lo dispuesto en un tratado o convención o en el derecho interno. Por «entrega» se entenderá:',
 o: ['la entrega de una persona por un Estado a la Corte de conformidad con lo dispuesto en el Estatuto.', 'la entrega de una persona por un Estado a otro Estado de conformidad con lo dispuesto en el Estatuto.', 'la entrega de una persona por la Corte a un Estado de conformidad con lo dispuesto en el Estatuto.', 'la entrega de una persona por un Estado a la Corte de conformidad con un tratado o convención.'],
 t: 'a) Por «entrega» se entenderá la entrega de una persona por un Estado a la Corte de conformidad con lo dispuesto en el presente Estatuto. b) Por «extradición» se entenderá la entrega de una persona por un Estado a otro Estado de conformidad con lo dispuesto en un tratado o convención o en el derecho interno', p: 'La entrega es a la Corte; la extradición, a otro Estado.'},
];
